<?php
namespace Dth\Crm\Services;
use Dth\Crm\Models\{Company,CompanyContact,CompanyMatchCandidate,Contact}; use Dth\Crm\Support\{Normalizer,CodeGenerator}; use Illuminate\Support\Facades\DB;
final class CompanyService {public function __construct(private Normalizer $n,private CodeGenerator $codes){}
 public function resolveOrCreate(array $data,?Contact $contact=null,?string $submissionRef=null):Company{return DB::transaction(function()use($data,$contact,$submissionRef){$tax=$this->n->taxCode($data['tax_code']??null);$domain=$this->n->domain($data['business_email']??$data['email']??null);$name=$data['company_name']??$data['legal_name']??'Doanh nghiệp';$normalized=$this->n->companyName($name);$c=$tax?Company::where('tax_code',$tax)->first():null;if(!$c&&$domain)$c=Company::where('email_domain',$domain)->first();if(!$c&&$normalized){$candidate=Company::where('normalized_name',$normalized)->first();if($candidate&&$contact){CompanyMatchCandidate::firstOrCreate(['submission_reference'=>$submissionRef,'contact_id'=>$contact->id,'suggested_company_id'=>$candidate->id],['confidence'=>65,'matched_by'=>'normalized_name','status'=>'pending']);}$c=$candidate;}if(!$c)$c=Company::create(['company_code'=>$this->codes->make('COM'),'legal_name'=>$name,'normalized_name'=>$normalized??strtolower($name),'tax_code'=>$tax,'email_domain'=>$domain,'phone'=>$data['business_phone']??$data['phone']??null,'normalized_phone'=>$this->n->phone($data['business_phone']??$data['phone']??null),'industry'=>$data['industry']??null,'address'=>$data['company_address']??null,'province'=>$data['province']??null,'source_submission_reference'=>$submissionRef,'metadata'=>$data['metadata']??[]]);if($contact)CompanyContact::updateOrCreate(['company_id'=>$c->id,'contact_id'=>$contact->id],['job_title'=>$data['contact_position']??null,'decision_role'=>$data['decision_role']??null,'is_primary'=>true,'is_active'=>true]);return $c;});}
}
